<script setup lang="ts">
import AdminConsole from '../console/AdminConsole.vue'
import ConsolePageHeading from '@orangezh1/qisvc-console-ui/components/ConsolePageHeading'
import ConsoleSettingsField from '@orangezh1/qisvc-console-ui/components/ConsoleSettingsField'
import ConsoleAccessLink from '../console/ConsoleAccessLink.vue'
import DecorationPreview from '../console/DecorationPreview.vue'
import PhonePreviewFrame from '../console/PhonePreviewFrame.vue'
import {decorationNavigation,decorationPageBackground,normalizeDecorationScheme} from '../../../../api/src/core/decoration-contract.mjs'
import {dateTime} from '../../utils/update-center'
import type {DecorationView} from '../../utils/decoration'
type PreviewLink={previewUrl:string;qrCode:string|null}
const auth=useApi('tenant'),tenantId=useTenantContext().tenantId.value,route=useRoute(),endpoint='/admin/tenants/'+encodeURIComponent(tenantId)+'/decoration'
const initial=await useAsyncData('current-decoration:'+auth.session.value?.id+':'+tenantId+':'+String(route.query.application||''),(_,{signal})=>auth.api<DecorationView>(endpoint+(typeof route.query.application==='string'?'?applicationKey='+encodeURIComponent(route.query.application):''),'GET',undefined,{signal}))
const data=ref(initial.data.value),error=ref(initial.error.value?.message||''),refreshing=ref(false),switching=ref(false),page=ref<'home'|'profile'>('home'),previewInfo=ref<PreviewLink|null>(null),previewError=ref(''),previewLoading=ref(false),previewAction=ref<'auto'|'generate'>('auto'),life=new AbortController()
let disposed=false,ready=false,previewAttempt=0,previewController:AbortController|undefined
const current=computed(()=>data.value?.current||data.value?.schemes[0]),unapplied=computed(()=>!!current.value&&(!data.value?.published||JSON.stringify(normalizeDecorationScheme(current.value.scheme))!==JSON.stringify(normalizeDecorationScheme(data.value.published))))
const pages=[{key:'home',label:'首页'},{key:'profile',label:'个人中心'}] as const
const editor=computed(()=>'/admin/decoration-editor?application='+encodeURIComponent(data.value?.applicationKey||'')+'&page='+page.value)
const imageUrl=(id:string)=>'/api/v1/admin/tenants/'+encodeURIComponent(tenantId)+'/materials/'+encodeURIComponent(data.value?.applicationKey||'')+'/'+encodeURIComponent(id)+'/content?purpose=library'
async function read(key=data.value?.applicationKey||'',action:'refresh'|'switch'='refresh'){if(refreshing.value||switching.value)return;const loading=action==='refresh'?refreshing:switching;loading.value=true;error.value='';try{const value=await auth.api<DecorationView>(endpoint+(key?'?applicationKey='+encodeURIComponent(key):''),'GET',undefined,{signal:life.signal});if(!disposed)data.value=value}catch(e:any){if(!disposed)error.value=e.message}finally{if(!disposed)loading.value=false}}
async function makePreview(action:'auto'|'generate'='auto'){
 const attempt=++previewAttempt;previewController?.abort();previewInfo.value=null;previewError.value='';previewLoading.value=false;if(!ready||!current.value||!data.value?.applicationKey)return;previewController=new AbortController();previewAction.value=action;previewLoading.value=true;previewInfo.value=null;previewError.value='';
 try{const value=await auth.api<PreviewLink>('/admin/tenants/'+encodeURIComponent(tenantId)+'/h5?applicationKey='+encodeURIComponent(data.value.applicationKey)+'&page='+page.value,'GET',undefined,{signal:previewController.signal});if(!disposed&&attempt===previewAttempt)previewInfo.value=value}catch(e:any){if(!disposed&&attempt===previewAttempt)previewError.value=e.message||'预览生成失败，请重试'}finally{if(!disposed&&attempt===previewAttempt)previewLoading.value=false}
}
watch(()=>[data.value?.applicationKey,data.value?.version,page.value],()=>{void makePreview()})
onMounted(()=>{ready=true;void makePreview()})
onBeforeUnmount(()=>{disposed=true;previewAttempt++;previewController?.abort();life.abort()})
</script>
<template><AdminConsole :refreshing="refreshing" @refresh="read()"><div class="decoration-overview-page"><ConsolePageHeading title="页面装修"/><UAlert v-if="error" color="error" :title="error"/><USelect v-if="data&&data.applications.length>1" :model-value="data.applicationKey||undefined" :items="data.applications.map(a=>({value:a.key,label:a.name}))" :disabled="refreshing||switching" :loading="switching" placeholder="选择应用" aria-label="选择装修应用" class="w-48" @update:model-value="read(String($event),'switch')"/>
<section v-if="current" class="decoration-overview"><div class="overview-preview"><div class="overview-page-tabs"><UButton v-for="entry in pages" :key="entry.key" color="neutral" :variant="page===entry.key?'solid':'ghost'" @click="page=entry.key">{{entry.label}}</UButton></div><div class="overview-phone"><PhonePreviewFrame :bottom-color="current.scheme.navigation.enabled?decorationNavigation(current.scheme).background:decorationPageBackground(current.scheme,page)"><DecorationPreview :assets="data?.assets" :components="data?.components" :scheme="normalizeDecorationScheme(current.scheme)" :page="page" :image-url="imageUrl" @navigate="($event==='home'||$event==='profile')&&(page=$event)"/></PhonePreviewFrame></div></div>
<div class="overview-details"><h2>当前装修</h2><dl class="overview-facts"><div><dt>当前页面</dt><dd>{{page==='home'?'首页':'个人中心'}}</dd></div><div><dt>保存状态</dt><dd>{{data?.currentSaved===false?'默认内容，尚未保存':unapplied?'有旧稿待保存生效':'已保存并生效'}}</dd></div><div v-if="current.updatedAt"><dt>最近保存</dt><dd>{{dateTime(current.updatedAt)}}</dd></div></dl><div class="overview-actions"><UButton :to="editor" target="_blank" rel="noopener" icon="i-lucide-pencil">{{data?.canWrite?'进入装修':'查看装修'}}</UButton><UButton :to="'/admin/decoration-templates?application='+encodeURIComponent(data?.applicationKey||'')" color="neutral" variant="outline" icon="i-lucide-bookmark">模板库</UButton></div>
<section class="overview-share"><div class="overview-share-heading"><h3>客户端预览</h3><UButton color="neutral" variant="ghost" size="sm" :disabled="previewLoading" @click="makePreview('generate')"><UIcon name="i-lucide-refresh-cw" :class="{'animate-spin':previewLoading&&previewAction==='generate'}"/>刷新入口</UButton></div><ConsoleSettingsField label="访问地址"><ConsoleAccessLink :url="previewInfo?.previewUrl||''" label="客户端预览地址"/></ConsoleSettingsField><ConsoleSettingsField label="访问二维码"><div class="overview-qr"><img v-if="previewInfo?.qrCode" :src="previewInfo.qrCode" :alt="(page==='home'?'首页':'个人中心')+'访问二维码'"><div v-else class="qr-state" role="status">{{previewLoading?'正在读取入口…':previewError||'暂无访问二维码'}}</div></div><p class="overview-help">打开当前生效页面，登录后显示真实资料与权益。</p><UButton v-if="previewError" color="neutral" variant="link" @click="makePreview('generate')">重试</UButton></ConsoleSettingsField></section></div></section><div v-else-if="data" class="py-12 text-center text-muted">选择已开通的应用后开始装修。</div>
</div></AdminConsole></template>
