@media(min-width:801px) and (max-height:760px){.overview-details{padding-top:8px}.overview-facts{margin:16px 0;gap:16px}.overview-facts>div{gap:6px}.overview-share{gap:16px;margin-top:20px;padding-top:16px}}
@media(max-width:800px){.decoration-overview-page{flex:none;min-height:auto}.decoration-overview{display:flex;flex-direction:column;flex:none;gap:24px}.overview-preview{height:520px;width:100%;padding:12px}.overview-details{width:100%;padding:0}:global(.decoration-overview-shell .qisvc-console-panel){height:auto!important;min-height:100dvh;overflow:visible!important}:global(.decoration-overview-shell .qisvc-console-panel-body){overflow:auto!important}:global(.decoration-overview-shell .console-frame-stage){height:auto!important;min-height:0}:global(.decoration-overview-shell .console-page-content){flex:none!important;min-height:auto!important}}
